param([Parameter(Mandatory)][string]$OutFile)
$target='1.1.1.1';$n=30;$p=@(Test-Connection $target -Count $n -ErrorAction SilentlyContinue);$recv=$p.Count;$loss=[math]::Round((1-$recv/$n)*100,1);$times=@($p|ForEach-Object ResponseTime);$avg=if($times){[math]::Round(($times|Measure -Average).Average,1)}else{0};$jit=0;if($times.Count -gt 1){$d=for($i=1;$i -lt $times.Count;$i++){[math]::Abs($times[$i]-$times[$i-1])};$jit=[math]::Round(($d|Measure -Average).Average,1)};@('PING / PERDIDA / JITTER',"Destino: $target","Enviados: $n | Recibidos: $recv | Perdida: $loss%","Ping medio: $avg ms","Jitter aproximado: $jit ms")|Set-Content $OutFile -Encoding UTF8
